/bin/bash -lc "python3 - <<'PY'
import json
from pathlib import Path
for f in ['snapshots/01-scope.json','snapshots/02-source-capture.json']:
 p=json.loads(Path(f).read_text()); print(f,'keys',list(p));
 if '01-' in f: print(json.dumps(p,indent=2)[:18000])
 else:
  for k,v in p.items():
   if isinstance(v,list):
    print(k,len(v))
    for x in v:
     if isinstance(x,dict) and x.get('source_id') in ['LAW','OJ','AMEND','CONSOLIDATED','TIME','FAQ']:print(json.dumps(x,indent=2)[:9000])
r=json.loads(Path('analysis/authority/request.json').read_text())
for e in r['extracts']:
 name=e['locator']['value'].split(' of ')[1].split(';')[0];t=e['text'];print('\\nSOURCE',name)
 if name in ['TIME','LAW']:print(t)
 else:
  import re
  pats=['Article 50','Article\\u00a050','Article 113','Article\\u00a0113','2026-','2027-','02024R','consolidated','Consolidated']
  for pat in pats:
   inds=[m.start() for m in re.finditer(re.escape(pat),t)]
   print('MATCHES',pat,len(inds))
   for i in inds[:8]:print(repr(t[max(0,i-180):i+500]))
PY"

