p=json.loads(Path('snapshots/02-source-capture.json').read_text())
print('STATE KEYS',list(p['state']))
for k,v in p['state'].items():
 if isinstance(v,list):
  for x in v:
   if isinstance(x,dict) and x.get('source_id') in ['LAW','OJ','AMEND','CONSOLIDATED','TIME','FAQ']:
    print(k,json.dumps(x,ensure_ascii=False)[:4500])
r=json.loads(Path('analysis/authority/request.json').read_text())
for e in r['extracts']:
 n=e['locator']['value'].split(' of ')[1].split(';')[0];t=e['text']
 if n in ['OJ','CONSOLIDATED']:
  print('\\n',n,'HEADER',t[3000:9500])
  for a,b in [('Article 50\\n','Article 51\\n'),('Article\\u00a050\\n','Article\\u00a051\\n'),('Article 113\\n','Done at')]:
   i=t.find(a); j=t.find(b,i+len(a))
   if i>=0:print(n,t[i:j if j>=0 else i+2200][:10500])
 if n=='AMEND':
  for pat in ['(20)\\nin Article','(39)\\nArticle','Article\\u00a04','Article 4']:
   i=t.find(pat);print(n,pat,t[i:i+3400])
 if n=='TIME':print(n,t)
PY"

